def expand(n,src,neutral):
    g=[[0]*n for _ in range(n)]; owner={}
    for r,c,col in src:
        g[r][c]=col
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            g[rr][cc]=3; owner[(rr,cc)]=(r,c)
    r,c=neutral
    for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        g[rr][cc]=3; owner[(rr,cc)]=neutral
    orig=[x[:] for x in g]; out=[x[:] for x in g]
    for r,c,col in src:
      for dr,dc,axis in ((0,1,'h'),(1,0,'v')):
       for s in (-1,1):
        rr,cc=r,c
        while 0<=rr<n and 0<=cc<n:
         if orig[rr][cc]==3 and owner.get((rr,cc))!=(r,c): break
         if not (axis=='h' and cc==neutral[1]) and orig[rr][cc]!=3: out[rr][cc]=col
         rr+=dr*s; cc+=dc*s
    return out
